-- Published once the city has five active rows and an intro
UPDATE "City" SET "published" = 1, "intro" = 'Colorado Springs has a Meetup group that plays at the library and a local club with classes. American Mahjong - COS meets at the Pikes Peak Library District''s Library 21c on Saturday afternoons and Monday mornings, and everyone is welcome to attend. Front Range Mahjong offers American Mahjong classes and events, and Courtney teaches private and group lessons using the official National Mah Jongg League card. Meetup games use sign-ups, so check each event before you go. If you are new, start with a Front Range Mahjong class or a beginner lesson with Courtney.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'colorado-springs';
UPDATE "City" SET "published" = 1, "intro" = 'Long Beach has a drop-in game at the Alpert Jewish Community Center, a social club that plays at a marina restaurant, and a teacher. The Alpert JCC runs Drop-In Mah Jongg on Monday evenings and Wednesday afternoons, open to everyone, with no instruction at the table. The Beach Bam Club hosts open play at San Pedro Fish Market, where tickets can sell out, and Mahj Club teaches the beginner series at the JCC. If you are new, ask Mahj Club about its beginner series before you join a drop-in game.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'long-beach';
